import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 조회 구분 값은 API 설명의 세 가지 이름 그대로 쓴다.
const BOX_TYPES = ['작성 문서', '공유 문서', '공유받은 문서'];
// 가정: ECM 문서 식별자는 ECM 연계 모듈이 없어 'ECM-' + 웹오피스 문서 ID로 만든다.
const ECM_ID_PREFIX = 'ECM-';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

@Controller('api/v1')
export class FnSfr04104Controller {
  @Post('/office-documents/:officeDocumentId/sync-ecm')
  @HttpCode(200)
  async syncOfficeDocumentToEcm(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const documentId = String(req.params['officeDocumentId']);
    if (!/^\d+$/.test(documentId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '웹오피스 문서 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT office_document_id AS "officeDocumentId", author_id AS "authorId", title, content, ecm_sync_status AS "ecmSyncStatus" FROM office_document WHERE office_document_id = CAST(:documentId AS bigint) FOR UPDATE',
        { documentId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'OFFICE_DOCUMENT_NOT_FOUND', '연계할 문서를 찾을 수 없습니다.');
      }
      const doc = found[0];
      if (doc.ecmSyncStatus === '완료') {
        throw new ApiError(409, 'ECM_DUPLICATE_DOCUMENT', 'ECM에 동일한 문서가 이미 있습니다.');
      }
      // 가정: 같은 작성자·같은 제목·같은 본문의 문서가 이미 ECM 연계 완료면 중복으로 본다.
      const same = await db.query(
        'SELECT COUNT(*) AS "cnt" FROM office_document WHERE office_document_id <> CAST(:documentId AS bigint) AND author_id = CAST(:authorId AS bigint) AND title = :title AND COALESCE(content, \'\') = COALESCE(CAST(:content AS text), \'\') AND ecm_sync_status = \'완료\'',
        { documentId, authorId: String(doc.authorId), title: doc.title, content: doc.content ?? null },
      );
      if (Number(same[0].cnt) > 0) {
        throw new ApiError(409, 'ECM_DUPLICATE_DOCUMENT', 'ECM에 동일한 문서가 이미 있습니다.');
      }
      const updated = await db.query(
        'UPDATE office_document SET ecm_document_id = CAST(:ecmId AS varchar), ecm_sync_status = \'완료\', ecm_synced_at = now(), ecm_fail_reason = NULL, updated_at = now() WHERE office_document_id = CAST(:documentId AS bigint) RETURNING office_document_id AS "officeDocumentId", ecm_document_id AS "ecmDocumentId", ecm_sync_status AS "ecmSyncStatus", ecm_fail_reason AS "ecmFailReason"',
        { documentId, ecmId: ECM_ID_PREFIX + documentId },
      );
      return updated[0];
    });
  }

  @Get('/ecm-documents')
  async listEcmDocuments(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const boxType = String(query['boxType'] ?? '').trim();
    if (boxType === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 구분을 선택해 주세요.');
    }
    if (!BOX_TYPES.includes(boxType)) {
      throw new ApiError(422, 'INVALID_DOCUMENT_BOX_TYPE', '조회 구분이 올바르지 않습니다.');
    }
    const title = String(query['title'] ?? '').trim();
    const createdFrom = String(query['createdFrom'] ?? '').trim();
    const createdTo = String(query['createdTo'] ?? '').trim();
    if (createdFrom !== '' && !DATE_PATTERN.test(createdFrom)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '작성일 시작 형식이 올바르지 않습니다.');
    }
    if (createdTo !== '' && !DATE_PATTERN.test(createdTo)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '작성일 종료 형식이 올바르지 않습니다.');
    }
    const pageText = String(query['page'] ?? '0');
    const sizeText = String(query['size'] ?? String(DEFAULT_SIZE));
    if (!/^\d+$/.test(pageText) || !/^\d+$/.test(sizeText) || Number(sizeText) < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 쪽 크기가 올바르지 않습니다.');
    }
    const page = Number(pageText);
    const size = Math.min(Number(sizeText), MAX_SIZE);
    // 가정: 공유 정보를 보관하는 테이블이 없어 공유 문서·공유받은 문서는 빈 목록으로 돌려준다.
    if (boxType !== '작성 문서') {
      return { items: [], page, size, total: 0 };
    }
    return transaction(async (db) => {
      const where = 'author_id = CAST(:userId AS bigint) AND (CAST(:title AS text) IS NULL OR title ILIKE \'%\' || CAST(:title AS text) || \'%\') AND (CAST(:createdFrom AS date) IS NULL OR created_at >= CAST(:createdFrom AS date)) AND (CAST(:createdTo AS date) IS NULL OR created_at < CAST(:createdTo AS date) + 1)';
      const filters = {
        userId: user.id,
        title: title === '' ? null : title,
        createdFrom: createdFrom === '' ? null : createdFrom,
        createdTo: createdTo === '' ? null : createdTo,
      };
      const totalRows = await db.query('SELECT COUNT(*) AS "total" FROM office_document WHERE ' + where, filters);
      const items = await db.query(
        'SELECT office_document_id AS "officeDocumentId", title, ecm_document_id AS "ecmDocumentId", ecm_sync_status AS "ecmSyncStatus" FROM office_document WHERE ' + where + ' ORDER BY office_document_id DESC LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { ...filters, size, offset: page * size },
      );
      return { items, page, size, total: Number(totalRows[0].total) };
    });
  }
}

