import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Tiles,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  TextInput,
  DateInput,
  Select,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const BOX_OPTIONS: [string, string][] = [
  ['작성 문서', '작성 문서'],
  ['공유 문서', '공유 문서'],
  ['공유받은 문서', '공유받은 문서'],
];
const PAGE_SIZE = 20;

export default function FnSfr04104Page({ role, notify }: PageProps) {
  const [boxType, setBoxType] = useState('작성 문서');
  const [title, setTitle] = useState('');
  const [createdFrom, setCreatedFrom] = useState('');
  const [createdTo, setCreatedTo] = useState('');
  const [applied, setApplied] = useState<Row>({ boxType: '작성 문서' });
  const [pageNo, setPageNo] = useState(0);
  const [target, setTarget] = useState<Row | null>(null);

  const list = useData<Page>(
    () => call<Page>('GET', '/ecm-documents', role, undefined, { ...applied, page: pageNo, size: PAGE_SIZE }),
    [applied, pageNo],
  );
  const rows = list.data?.items ?? [];
  const total = list.data?.total ?? 0;
  const waiting = rows.filter((r) => r['ecmSyncStatus'] !== '완료').length;

  const search = () => {
    if (boxType === '') {
      notify('조회 구분을 선택해 주세요.');
      return;
    }
    setPageNo(0);
    setApplied({ boxType, title, createdFrom, createdTo });
  };

  const reset = () => {
    setBoxType('작성 문서');
    setTitle('');
    setCreatedFrom('');
    setCreatedTo('');
    setPageNo(0);
    setApplied({ boxType: '작성 문서' });
  };

  const sync = async () => {
    if (!target) return;
    await call('POST', '/office-documents/' + target['officeDocumentId'] + '/sync-ecm', role, {});
    notify('ECM에 연계했습니다.');
    setTarget(null);
    list.reload();
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>연계 현황</h2>
        <Tiles items={[['조회 건수', total], ['현재 쪽 미연계', waiting]]} />
      </section>
      <section className="box span-12">
        <h2>ECM 문서</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 구분" required>
            <Select value={boxType} onChange={setBoxType} options={BOX_OPTIONS} />
          </Field>
          <Field label="문서 제목">
            <TextInput value={title} onChange={setTitle} />
          </Field>
          <Field label="작성일 시작">
            <DateInput value={createdFrom} onChange={setCreatedFrom} />
          </Field>
          <Field label="작성일 종료">
            <DateInput value={createdTo} onChange={setCreatedTo} />
          </Field>
        </Filters>
        <Band total={total} />
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable
          rows={rows}
          empty="조회된 문서가 없습니다."
          columns={[
            { key: 'title', label: '문서 제목' },
            { key: 'ecmDocumentId', label: 'ECM 문서 식별자' },
            { key: 'ecmSyncStatus', label: 'ECM 연계 상태', render: (r) => <Badge value={r['ecmSyncStatus']} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) =>
                r['ecmSyncStatus'] !== '완료' ? (
                  <button type="button" onClick={() => setTarget(r)}>
                    ECM 연계
                  </button>
                ) : null,
            },
          ]}
        />
        <Pager page={pageNo} size={PAGE_SIZE} total={total} onPage={setPageNo} />
      </section>
      {target ? (
        <Drawer title="ECM 연계" onClose={() => setTarget(null)}>
          <Pairs
            items={[
              ['문서 제목', String(target['title'] ?? '')],
              ['ECM 연계 상태', <Badge value={target['ecmSyncStatus']} />],
            ]}
          />
          <Form onSubmit={sync} submit="ECM에 연계" note="이 문서를 ECM에 연계 저장합니다." />
        </Drawer>
      ) : null}
    </div>
  );
}
